import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 36 A chance in a million","description":"学习 so 与 such 的结果结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 36 A chance in a million","description":"学习 so 与 such 的结果结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 so 与 such 的结果结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 35 Justice was done","link":"/life/english/new-concept/book-3/unit-02/lesson-035"},"next":{"text":"第三册：培养技能 · Lesson 37 The Westhaven Express","link":"/life/english/new-concept/book-3/unit-02/lesson-037"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 35 Justice was done","link":"/life/english/new-concept/book-3/unit-02/lesson-035"},"next":{"text":"第三册：培养技能 · Lesson 37 The Westhaven Express","link":"/life/english/new-concept/book-3/unit-02/lesson-037"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-036.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-036.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-036.md"};function s(l,e,r,c,h,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-36-a-chance-in-a-million" tabindex="-1">第三册：培养技能 · Lesson 36 A chance in a million <a class="header-anchor" href="#第三册-培养技能-·-lesson-36-a-chance-in-a-million" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 36 A chance in a million&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以偶遇和巧合为主题，练习表达惊讶而不夸大统计结论。两件事碰巧同时发生不等于存在因果联系，也不应凭感觉给出精确概率。学习 so 与 such 的感叹和结果结构，通过具体细节解释为什么一场相遇让叙述者觉得罕见。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>coincidence</td><td>/kəʊˈɪnsɪdəns/</td><td>n.</td><td>巧合</td><td>a remarkable coincidence</td></tr><tr><td>encounter</td><td>/ɪnˈkaʊntə/</td><td>n.</td><td>偶遇</td><td>an unexpected encounter</td></tr><tr><td>unlikely</td><td>/ʌnˈlaɪkli/</td><td>adj.</td><td>不大可能的</td><td>an unlikely event</td></tr><tr><td>connection</td><td>/kəˈnekʃən/</td><td>n.</td><td>联系</td><td>a family connection</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>by coincidence — 碰巧</li><li>run into — 偶然遇见某人</li></ul><h2 id="语法讲解-so-与-such-的结果结构" tabindex="-1">语法讲解：so 与 such 的结果结构 <a class="header-anchor" href="#语法讲解-so-与-such-的结果结构" aria-label="Permalink to &quot;语法讲解：so 与 such 的结果结构&quot;">​</a></h2><p>so 后通常接形容词或副词，such 后通常接名词短语。单数可数名词常用 such a 加形容词加名词，如 such a strange meeting；so many 加复数名词、so much 加不可数名词则是数量结构。后接 that 从句可表示结果，但 that 有时在口语中省略。so ... that 不能与目的连词 so that 混为一谈。夸张性的日常概率词不等于计算结果，写说明文时应避免把感叹修辞当成统计证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>It was such an unexpected meeting that neither of us spoke for a moment.</p></blockquote><p>这场相遇太出乎意料，我们两人一时都没说话。</p><p>such 修饰 an unexpected meeting 这一名词短语；that 从句表达惊讶造成的反应。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>so an unexpected meeting 位置错误；可写 such an unexpected meeting，或 the meeting was so unexpected。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 such a surprising coincidence 时保持名词短语连贯；在 both 和 same 上重读，让听者理解巧合的具体内容。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I found my former classmate in a tiny bookshop abroad. We had both come to buy the same dictionary. It was such a surprising coincidence that we forgot to ask the price.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句巧合经历，不编造具体概率。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>细节说明惊讶原因，未将罕见感受包装成数学概率。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：There were ___ many similarities that we laughed.（so/such）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> so</p><p><strong>解析：</strong> many 的数量结构用 so many。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句中的 that 从句表示目的还是结果？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 结果。</p><p><strong>解析：</strong> 沉默是出乎意料相遇后的反应。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>neither of us 指几个人中的几个？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两个人都不。</p><p><strong>解析：</strong> neither 通常用于两者的否定。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：so 与 such 的结果结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-037">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
